<?php
namespace App\Console\Commands;
use App\Models\OrderItem;use App\Notifications\StoreNotification;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;
class SendSubscriptionReminders extends Command{protected $signature='subscriptions:remind';protected $description='Send due subscription expiry reminders';public function handle():int{$today=now()->timezone(config('app.timezone'))->startOfDay();$sent=0;OrderItem::query()->with('order.user')->whereNotNull('service_expires_at')->where('service_expires_at','<=',$today->copy()->addDays(8)->utc())->whereHas('order',fn($q)=>$q->where('status','completed'))->chunkById(100,function($items)use($today,&$sent){foreach($items as $item){$user=$item->order?->user;if(!$user)continue;$expiry=$item->service_expires_at->timezone(config('app.timezone'))->startOfDay();$days=(int)$today->diffInDays($expiry,false);if($days>0&&!in_array($days,[7,3,1],true))continue;$expired=$days<=0;$key=$expired?'expired':"day_{$days}";$created=DB::table('subscription_reminders')->insertOrIgnore(['order_item_id'=>$item->id,'reminder_key'=>$key,'sent_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);if(!$created)continue;$date=$expiry->format('Y-m-d');$title=$expired?'Service သက်တမ်းကုန်ဆုံးပါပြီ':"Service သက်တမ်းကုန်ရန် {$days} ရက်ကျန်";$message=$expired?"{$item->product_name} သက်တမ်းသည် {$date} တွင် ကုန်ဆုံးပါပြီ။ ဆက်သုံးလိုပါက သက်တမ်းတိုးနိုင်ပါသည်။":"{$item->product_name} သက်တမ်းသည် {$date} တွင် ကုန်ဆုံးပါမည်။ ဆက်သုံးလိုပါက ကြိုတင်သက်တမ်းတိုးပါ။";$user->notify(new StoreNotification($title,$message));$sent++;}});$this->info("Sent {$sent} subscription reminders.");return self::SUCCESS;}}
